DROP TABLE IF EXISTS `kontrak_pks`;
CREATE TABLE `kontrak_pks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `po_id` int(11) NOT NULL,
  `nomor_pks_klien` varchar(100) NOT NULL,
  `nomor_pks_bbspjis` varchar(100) NOT NULL,
  `nama_penandatangan_klien` varchar(100) NOT NULL,
  `jabatan_penandatangan_klien` varchar(100) NOT NULL,
  `nama_penandatangan_bbspjis` varchar(100) NOT NULL,
  `jabatan_penandatangan_bbspjis` varchar(100) NOT NULL,
  `ruang_lingkup` text NOT NULL,
  `target_mulai` date NOT NULL,
  `target_selesai` date NOT NULL,
  `nilai_kontrak` decimal(15,2) DEFAULT 0.00,
  `ketentuan_pembayaran` text DEFAULT NULL,
  `nomor_va` varchar(50) DEFAULT NULL,
  `tanggal_ttd` date DEFAULT NULL,
  `status_ttd` enum('belum','sudah') DEFAULT 'belum',
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `po_id` (`po_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `metode_uji`;
CREATE TABLE `metode_uji` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kategori_id` int(11) NOT NULL,
  `nama_metode` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `deskripsi_kegunaan` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `peralatan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `durasi_nilai` int(11) NOT NULL DEFAULT 1,
  `durasi_satuan` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Bulan',
  `butuh_eksternal` tinyint(1) NOT NULL DEFAULT 0,
  `harga` decimal(15,2) NOT NULL DEFAULT 0.00,
  `jumlah_sampel` int(11) NOT NULL DEFAULT 1,
  `status` enum('aktif','nonaktif') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'aktif',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_kategori_id` (`kategori_id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

