DROP TABLE IF EXISTS `opti_bast`;
CREATE TABLE `opti_bast` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `po_id` int(11) DEFAULT NULL,
  `nomor_bast` varchar(100) NOT NULL,
  `tanggal_bast` date NOT NULL,
  `pihak_pertama_nama` varchar(100) NOT NULL DEFAULT 'Kepala BBSPJIS',
  `pihak_pertama_jabatan` varchar(100) NOT NULL DEFAULT 'Kepala Balai Besar',
  `pihak_kedua_nama` varchar(100) NOT NULL,
  `pihak_kedua_jabatan` varchar(100) NOT NULL,
  `judul_pekerjaan` varchar(255) NOT NULL,
  `ringkasan_serah_terima` text DEFAULT NULL,
  `file_dokumen_bast` varchar(255) DEFAULT NULL,
  `status_bast` enum('draft','proses_ttd','selesai') DEFAULT 'draft',
  `status_penutupan` enum('aktif','selesai_diarsipkan') DEFAULT 'aktif',
  `catatan_penutupan` text DEFAULT NULL,
  `closed_by` int(11) DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `nomor_bast` (`nomor_bast`),
  KEY `order_id` (`order_id`),
  KEY `po_id` (`po_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4;

