DROP TABLE IF EXISTS `opti_invoice`;
CREATE TABLE `opti_invoice` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `po_id` int(11) DEFAULT NULL,
  `nomor_invoice` varchar(100) NOT NULL,
  `tanggal_invoice` date NOT NULL,
  `jatuh_tempo` date NOT NULL,
  `nominal_tagihan` decimal(15,2) NOT NULL DEFAULT 0.00,
  `keterangan_termin` varchar(255) DEFAULT NULL,
  `status_pembayaran` enum('belum_bayar','sebagian','lunas') DEFAULT 'belum_bayar',
  `file_invoice` varchar(255) DEFAULT NULL,
  `dibuat_oleh` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `nomor_invoice` (`nomor_invoice`),
  KEY `idx_order` (`order_id`),
  KEY `idx_po` (`po_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `opti_kalkulasi_uji_lingkungan`;
CREATE TABLE `opti_kalkulasi_uji_lingkungan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `sub_layanan` enum('uji_laboratorium','lpv','kajian_lab','konsultansi') DEFAULT 'uji_laboratorium',
  `metode_uji_id` int(11) DEFAULT NULL,
  `nama_pengujian` varchar(200) NOT NULL,
  `standar_rujukan` varchar(100) DEFAULT NULL,
  `tarif_per_sampel` decimal(15,2) NOT NULL DEFAULT 0.00,
  `jumlah_sampel` int(11) NOT NULL DEFAULT 1,
  `total_biaya_item` decimal(15,2) NOT NULL DEFAULT 0.00,
  `durasi_nilai` int(11) DEFAULT NULL,
  `durasi_satuan` varchar(50) DEFAULT 'Hari Kerja',
  `durasi_bulan` int(11) NOT NULL DEFAULT 1,
  `is_subkontrak` tinyint(1) DEFAULT 0,
  `lab_eksternal_id` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4;

INSERT INTO `opti_kalkulasi_uji_lingkungan` (`id`, `order_id`, `sub_layanan`, `metode_uji_id`, `nama_pengujian`, `standar_rujukan`, `tarif_per_sampel`, `jumlah_sampel`, `total_biaya_item`, `durasi_nilai`, `durasi_satuan`, `durasi_bulan`, `is_subkontrak`, `lab_eksternal_id`, `created_at`) VALUES ('5', '13', 'uji_laboratorium', '17', 'Uji Biodegradasi Aerobik Pengomposan Terkendali (ISO 14855-2)', 'ISO 14855-2', '47000000.00', '1', '47000000.00', '9', 'Hari Kerja', '1', '0', NULL, '2026-09-15 09:46:07');
