DROP TABLE IF EXISTS `opti_notifikasi`;
CREATE TABLE `opti_notifikasi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) DEFAULT NULL,
  `po_id` int(11) DEFAULT NULL,
  `target_role` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all',
  `target_user_id` int(11) DEFAULT NULL,
  `target_layanan` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'semua',
  `judul` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pesan` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipe` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'info',
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'bi-bell-fill',
  `link_url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '/order',
  `is_read` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` int(11) DEFAULT NULL,
  `created_by_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_notif_role` (`target_role`,`target_layanan`,`is_read`),
  KEY `idx_notif_user` (`target_user_id`,`is_read`),
  KEY `idx_notif_order` (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

