DROP TABLE IF EXISTS `order_layanan`;
CREATE TABLE `order_layanan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_customer` int(11) NOT NULL,
  `nomor_order` varchar(50) NOT NULL,
  `tanggal_masuk` date NOT NULL,
  `judul_kegiatan` varchar(200) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `spm_layanan` varchar(150) NOT NULL DEFAULT 'Lainnya',
  `tanggal_deadline_spm` date DEFAULT NULL,
  `durasi_hari_kerja` int(11) DEFAULT 30,
  `jenis_layanan_opti` enum('selulosa','lingkungan','belum_ditentukan') DEFAULT 'belum_ditentukan',
  `status_rancop` enum('draft','diskusi','deal','batal') NOT NULL DEFAULT 'draft',
  `log_diskusi_klien` text DEFAULT NULL,
  `tahapan_riset_json` longtext DEFAULT NULL,
  `lokasi_pelaksanaan` enum('internal','lapangan') NOT NULL DEFAULT 'internal',
  `lab_internal` varchar(100) DEFAULT NULL,
  `lokasi_lapangan` text DEFAULT NULL,
  `tipe_data_sampel` varchar(100) DEFAULT NULL,
  `jenis_sampel` varchar(150) DEFAULT NULL,
  `tanggal_terima_sampel` date DEFAULT NULL,
  `volume_berat` varchar(100) DEFAULT NULL,
  `karakteristik_serat` text DEFAULT NULL,
  `karakteristik_kimia` text DEFAULT NULL,
  `jumlah_pekerjaan` varchar(100) NOT NULL,
  `estimasi_biaya` decimal(15,2) DEFAULT 0.00,
  `diskon_penawaran` decimal(15,2) DEFAULT 0.00,
  `status` enum('permintaan_masuk','baru','draft','draft_disimpan','disetujui','ditolak','selesai') NOT NULL DEFAULT 'permintaan_masuk',
  `status_tinjauan` enum('belum_ditinjau','layak','tidak_layak') DEFAULT 'belum_ditinjau',
  `status_proposal_biaya` enum('draft','draft_disimpan','menunggu_approval','siap_penawaran') DEFAULT 'draft',
  `status_penawaran` enum('belum_ada','draft','terkirim','nego','deal','batal') DEFAULT 'belum_ada',
  `status_keuangan` enum('belum_ditagih','menunggu_pembayaran','terbayar_sebagian','lunas') DEFAULT 'belum_ditagih',
  `status_pelaksanaan` enum('belum_mulai','sedang_berjalan','evaluasi_laporan','revisi_laporan','laporan_selesai') DEFAULT 'belum_mulai',
  `diklaim_oleh` int(11) DEFAULT NULL,
  `pic_proposal_id` int(11) DEFAULT NULL,
  `surat_penawaran_id` int(11) DEFAULT NULL,
  `tanggal_klaim` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `id_surat_masuk` int(11) DEFAULT NULL,
  `alasan_tolak` text DEFAULT NULL,
  `tanggal_tolak` datetime DEFAULT NULL,
  `ditolak_oleh` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nomor_order` (`nomor_order`),
  KEY `idx_order_customer` (`id_customer`),
  KEY `fk_order_surat_masuk` (`id_surat_masuk`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4;

