DROP TABLE IF EXISTS `pengujian_eksternal`;
CREATE TABLE `pengujian_eksternal` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `metode_id` int(11) NOT NULL,
  `nama_lembaga` varchar(255) NOT NULL,
  `alamat` text DEFAULT NULL,
  `pic_nama` varchar(150) DEFAULT NULL,
  `pic_kontak` varchar(100) DEFAULT NULL,
  `no_akreditasi` varchar(100) DEFAULT NULL,
  `estimasi_biaya` decimal(15,2) DEFAULT 0.00,
  `estimasi_nilai` int(11) DEFAULT 1,
  `estimasi_satuan` varchar(50) DEFAULT 'Bulan',
  `keterangan` text DEFAULT NULL,
  `status` enum('aktif','nonaktif') DEFAULT 'aktif',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_metode_id` (`metode_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4;

INSERT INTO `pengujian_eksternal` (`id`, `metode_id`, `nama_lembaga`, `alamat`, `pic_nama`, `pic_kontak`, `no_akreditasi`, `estimasi_biaya`, `estimasi_nilai`, `estimasi_satuan`, `keterangan`, `status`, `created_at`, `updated_at`) VALUES ('1', '1', 'Laboratorium Uji Terpadu IPB', 'Kampus IPB Dramaga, Bogor', 'Dr. Ir. Budi Santoso', '081234567890', 'LP-123-IDN', '1500000.00', '14', 'Hari', 'Rujukan uji instrumen ICP-MS dan GC-MS', 'aktif', '2026-08-26 08:32:21', '2026-08-26 08:32:21');

DROP TABLE IF EXISTS `po`;
CREATE TABLE `po` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `nomor_po` varchar(50) NOT NULL,
  `biaya` decimal(15,2) DEFAULT 0.00,
  `tim_kerja` varchar(150) DEFAULT NULL,
  `status` enum('belum_upload','sudah_upload','on_proses','kembali_selesai') DEFAULT 'belum_upload',
  `tanggal_keluar` date DEFAULT NULL,
  `tanggal_kembali` date DEFAULT NULL,
  `target_mulai` date DEFAULT NULL,
  `target_selesai` date DEFAULT NULL,
  `realisasi_selesai` date DEFAULT NULL,
  `auto_realisasi_dari_upload` tinyint(1) DEFAULT 0,
  `app_proposal` tinyint(1) DEFAULT 0,
  `app_proposal_date` datetime DEFAULT NULL,
  `app_proposal_val` tinyint(1) DEFAULT 0,
  `app_proposal_val_date` datetime DEFAULT NULL,
  `app_kontrak` tinyint(1) DEFAULT 0,
  `app_kontrak_date` datetime DEFAULT NULL,
  `app_kontrak_val` tinyint(1) DEFAULT 0,
  `app_kontrak_val_date` datetime DEFAULT NULL,
  `app_po_adm` tinyint(1) DEFAULT 0,
  `app_po_adm_date` datetime DEFAULT NULL,
  `app_po_mitra` tinyint(1) DEFAULT 0,
  `app_po_mitra_date` datetime DEFAULT NULL,
  `app_po_ppk` tinyint(1) DEFAULT 0,
  `app_po_ppk_date` datetime DEFAULT NULL,
  `app_po_kabag` tinyint(1) DEFAULT 0,
  `app_po_kabag_date` datetime DEFAULT NULL,
  `app_dist_tu` tinyint(1) DEFAULT 0,
  `app_dist_tu_date` datetime DEFAULT NULL,
  `app_dist_kepeg` tinyint(1) DEFAULT 0,
  `app_dist_kepeg_date` datetime DEFAULT NULL,
  `app_dist_keu` tinyint(1) DEFAULT 0,
  `app_dist_keu_date` datetime DEFAULT NULL,
  `evaluasi_status` enum('pending','disetujui','perlu_revisi') DEFAULT 'pending',
  `notulen_evaluasi` text DEFAULT NULL,
  `tgl_evaluasi` date DEFAULT NULL,
  `laporan_akhir` text DEFAULT NULL,
  `nomor_laporan_hasil` varchar(100) DEFAULT NULL,
  `file_draf_laporan` varchar(255) DEFAULT NULL,
  `file_laporan_final` varchar(255) DEFAULT NULL,
  `catatan_revisi_laporan` text DEFAULT NULL,
  `bast_dokumen` varchar(255) DEFAULT NULL,
  `tgl_bast` date DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_id` (`order_id`),
  UNIQUE KEY `nomor_po` (`nomor_po`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `po_kegiatan`;
CREATE TABLE `po_kegiatan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `nomor_po` varchar(100) DEFAULT NULL,
  `judul_kegiatan` varchar(255) DEFAULT NULL,
  `dasar` text DEFAULT NULL,
  `tujuan` text DEFAULT NULL,
  `ruang_lingkup` longtext DEFAULT NULL,
  `alamat` text DEFAULT NULL,
  `alat_bahan` longtext DEFAULT NULL,
  `tim_pelaksana` longtext DEFAULT NULL,
  `rab` longtext DEFAULT NULL,
  `jadwal` longtext DEFAULT NULL,
  `jadwal_mulai` date DEFAULT NULL,
  `jadwal_selesai` date DEFAULT NULL,
  `status` enum('draft','kirim') DEFAULT 'draft',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `po_log_status`;
CREATE TABLE `po_log_status` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `po_id` int(11) NOT NULL,
  `status_lama` varchar(50) DEFAULT NULL,
  `status_baru` varchar(50) NOT NULL,
  `catatan` varchar(255) DEFAULT NULL,
  `tanggal` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `po_id` (`po_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `po_rincian_anggaran`;
CREATE TABLE `po_rincian_anggaran` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `po_id` int(11) NOT NULL,
  `kategori` varchar(100) NOT NULL,
  `deskripsi` varchar(255) NOT NULL,
  `nominal` decimal(15,2) NOT NULL DEFAULT 0.00,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `po_id` (`po_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


DROP TABLE IF EXISTS `surat_masuk`;
CREATE TABLE `surat_masuk` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nomor_surat` varchar(100) NOT NULL,
  `pengirim` varchar(255) DEFAULT NULL,
  `pt_cv` varchar(20) DEFAULT 'PT',
  `alamat_pengirim` text DEFAULT NULL,
  `pic_pengirim` varchar(100) DEFAULT NULL,
  `no_telp_pengirim` varchar(50) DEFAULT NULL,
  `email_pengirim` varchar(100) DEFAULT NULL,
  `tanggal_surat` date NOT NULL,
  `nama_pengirim` varchar(255) NOT NULL,
  `perihal` varchar(255) NOT NULL,
  `file_path` varchar(255) DEFAULT NULL,
  `layanan` varchar(100) NOT NULL DEFAULT 'opti',
  `status_ambil` enum('belum','sudah') NOT NULL DEFAULT 'belum',
  `id_order_layanan` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `created_by` int(11) NOT NULL,
  `status_tolak` tinyint(1) DEFAULT 0,
  `alasan_tolak` text DEFAULT NULL,
  `ditolak_oleh` int(11) DEFAULT NULL,
  `tanggal_tolak` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_sm_created_by` (`created_by`),
  KEY `idx_sm_order_layanan` (`id_order_layanan`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4;

