DROP TABLE IF EXISTS `surat_penawaran_mitra`;
CREATE TABLE `surat_penawaran_mitra` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nomor_surat` varchar(100) DEFAULT NULL,
  `nama_mitra` varchar(255) DEFAULT NULL,
  `perusahaan` varchar(255) DEFAULT NULL,
  `alamat` text DEFAULT NULL,
  `perihal` varchar(255) DEFAULT NULL,
  `jenis_layanan` enum('selulosa','lingkungan') DEFAULT 'selulosa',
  `nominal_penawaran` decimal(15,2) DEFAULT 0.00,
  `tanggal_surat` date DEFAULT NULL,
  `keterangan` text DEFAULT NULL,
  `status` enum('draft','final') DEFAULT 'draft',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


