DROP TABLE IF EXISTS `tb_surat_keluar`;
CREATE TABLE `tb_surat_keluar` (
  `id_surat_keluar` int(11) NOT NULL AUTO_INCREMENT,
  `no_surat` varchar(60) DEFAULT NULL,
  `tanggal_surat` date DEFAULT NULL,
  `perihal_surat` varchar(255) DEFAULT NULL,
  `jabatan_surat` varchar(255) DEFAULT NULL,
  `id_customer` int(11) NOT NULL DEFAULT 0,
  `id_klasifikasi` int(11) DEFAULT NULL,
  `keterangan` varchar(255) DEFAULT NULL,
  `nama_berkas_surat_keluar` varchar(255) DEFAULT NULL,
  `tanggal_simpan` datetime DEFAULT NULL,
  `id_arsip` int(11) NOT NULL DEFAULT 0,
  `surat_penawaran` enum('Y','N') DEFAULT 'N',
  `biaya_pengujian` enum('Y','N') DEFAULT 'N',
  `biaya_sertifikasi` enum('Y','N') DEFAULT 'N',
  `biaya_opti` enum('Y','N') DEFAULT 'N',
  `dipilih_sis_pengujian` enum('Y','N') DEFAULT 'N',
  `dipilih_sis_sertifikasi` enum('Y','N') DEFAULT 'N',
  `dipilih_sis_opti` enum('Y','N') DEFAULT 'N',
  `id_surat_keluar_dipilih` int(11) DEFAULT NULL,
  PRIMARY KEY (`id_surat_keluar`),
  KEY `idx_surat_penawaran_opti` (`surat_penawaran`,`dipilih_sis_opti`),
  KEY `idx_id_arsip` (`id_arsip`),
  KEY `idx_id_customer` (`id_customer`)
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=latin1;

