DROP TABLE IF EXISTS `tb_surat_penawaran`;
CREATE TABLE `tb_surat_penawaran` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) DEFAULT NULL,
  `order_id` int(11) DEFAULT NULL,
  `nomor_surat` varchar(100) DEFAULT NULL,
  `perihal` varchar(255) DEFAULT NULL,
  `nominal_penawaran` decimal(15,2) DEFAULT 0.00,
  `tanggal_surat` date DEFAULT NULL,
  `jenis_layanan` varchar(100) DEFAULT NULL,
  `nama` varchar(255) DEFAULT NULL,
  `perusahaan` varchar(255) DEFAULT NULL,
  `alamat` text DEFAULT NULL,
  `permintaan_melalui` varchar(100) DEFAULT NULL,
  `pegawai_id` int(11) DEFAULT NULL,
  `kirim_ke` varchar(100) DEFAULT NULL,
  `bidang` varchar(100) DEFAULT NULL,
  `bidang_lainnya` varchar(255) DEFAULT NULL,
  `penjelasan` text DEFAULT NULL,
  `file_lampiran` varchar(255) DEFAULT NULL,
  `status` varchar(50) DEFAULT 'draft',
  `status_respon_klien` enum('draft','terkirim','nego','deal','batal') DEFAULT 'draft',
  `catatan_nego` text DEFAULT NULL,
  `disetujui_klien_at` datetime DEFAULT NULL,
  `dibuat_oleh` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4;

